with enriched as (select id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, row_number() over (order by salary, id) as event_seq, row_number() over w_grp as seq_no from employees window w_grp as (order by hire_date, id)) select s.id, s.full_name, s.email, s.manager_id, s.job_title, s.hire_date, s.event_seq, s.seq_no, (select max(t2.salary) from employees t2 where t2.manager_id = s.manager_id) as max_employee_salary from enriched s order by max_employee_salary desc nulls first, id limit 20;
